import * as A from './installer-analytics-views.js';
import * as X from './installer-experiences.js';
import * as D from './domain.js';
import {escapeHtml as e} from './exports.js';
const n=x=>x==null?'—':x.toLocaleString('en-IE');
// Recent history stays visible. Older records are expandable, not discarded.
const historyList=(items,label,format)=>{
 const reversed=[...items].reverse(),recent=reversed.slice(0,10),older=reversed.slice(10);
 return recent.map(format).join('')+(older.length?`<details class="installer-history-older"><summary>Show ${older.length} older ${label}</summary>${older.map(format).join('')}</details>`:'');
};
const unionHistoryLine=h=>`<p>${e(h.before.map(a=>a.name).join(' + '))} → <strong>${e(h.after.name)}</strong> · ${e(h.timestamp)} ${h.undone?'(undone)':`<button class="small" data-installer-unmerge="${e(h.id)}">Undo union</button>`}</p>`;
const importHistoryLine=h=>`<p>${e(h.filename)} · ${h.changes.length} changed monthly values · ${e(h.timestamp)} ${h.undone?'(undone)':`<button class="small" data-installer-undo-import="${e(h.id)}">Undo import</button>`}</p>`;

export function installerView(state,ui){
 const tab=ui.installerTab??'overview';
 if(tab==='profile'||tab==='compare'||tab==='insights')return `<div class="page-title"><div><div class="eyebrow">Ireland · Digital Power</div><h1>Installers</h1><p>Explore individual accounts and compare tracked activity.</p></div></div>${X.installerTabNav(tab)}${tab==='profile'?X.installerProfilePage(state,ui):tab==='compare'?X.installerComparisonPage(state,ui):X.installerInsightsPage(state,ui)}`;
  const d=state.installers,f=D.installerFilters(state),report=D.installerAnalysis(state,f,{cohort:ui.installerCohort??'all'}),rows=D.sortInstallerRanking(report.rows,ui.installerSort??'volume').map(r=>({...r,total:r.current.value,observed:r.current.observed,expected:r.current.expected})),query=(ui.installerSearch??'').toLowerCase(),filtered=rows.filter(r=>r.name.toLowerCase().includes(query)||r.aliases.some(a=>a.toLowerCase().includes(query))),page=Math.min(ui.installerPage??0,Math.max(0,Math.ceil(filtered.length/50)-1)),shown=filtered.slice(page*50,page*50+50),selected=ui.installerSelected??new Set(),suggestions=D.installerSuggestions(state);
  const table=`<div class="table-wrap"><table><thead><tr><th>Select</th><th>Installer</th><th class="num">Reported activations</th><th>Previous</th><th>Change</th><th>Growth</th><th>Share</th><th>Rank</th><th>3M momentum</th><th>Reporting coverage</th><th>Source names</th></tr></thead><tbody>${shown.map(r=>`<tr><td><input type="checkbox" data-installer-select="${e(r.id)}" aria-label="Select ${e(r.name)}" ${selected.has(r.id)?'checked':''}></td><td><button class="quiet" data-installer-detail="${e(r.id)}">${e(r.name)}</button><button class="quiet installer-profile-link" data-installer-fullprofile="${e(r.id)}" aria-label="Open full profile for ${e(r.name)}">Full profile</button></td><td class="num">${n(r.total)}</td><td>${n(r.previous.value)}</td><td>${n(r.delta)}</td><td>${r.pct==null?'—':n(Math.round(r.pct*10)/10)+'%'}</td><td>${r.share==null?'—':n(Math.round(r.share*10)/10)+'%'}</td><td>${n(r.rank)}</td><td>${r.momentum.pct==null?'—':n(Math.round(r.momentum.pct*10)/10)+'%'}</td><td>${r.observed} / ${r.expected}${r.current.complete?'':' *'}</td><td>${r.aliases.map(e).join('<br>')}</td></tr>`).join('')||'<tr><td colspan="11">No installers in this view. Use Data → Installer imports to start.</td></tr>'}</tbody></table></div>`;
  const ranking=`<section class="panel"><div class="panel-head"><h2>Installer ranking (${rows.length})</h2><button class="primary" data-action="installer-compare-from-selected" ${selected.size<2||selected.size>6?'disabled':''}>Compare selected (${selected.size})</button></div><label class="field">Search installer or source name<input id="installer-search" type="search" value="${e(ui.installerSearch??'')}" placeholder="e.g. Bord Gáis"></label><label class="field">Sort ranking<select id="installer-sort">${[['volume','Activations'],['change','Change in units'],['growth','Growth %'],['momentum','3M momentum'],['name','Name']].map(([v,t])=>`<option value="${v}" ${(ui.installerSort??'volume')===v?'selected':''}>${t}</option>`).join('')}</select></label>${table}<div class="panel-actions"><button data-installer-page="${page-1}" ${page===0?'disabled':''}>Previous</button><span>${filtered.length} matches · page ${page+1} of ${Math.max(1,Math.ceil(filtered.length/50))}</span><button data-installer-page="${page+1}" ${(page+1)*50>=filtered.length?'disabled':''}>Next</button></div><p class="table-note">Select 2–6 accounts to compare their reported activity. Click an installer to inspect its source values. Identity unions are reviewed separately under Account management. Rank uses reported volume, with tied values sharing a rank. * Incomplete source coverage or open period. Shares require a complete selected base. 3M momentum compares the last three months ending at the selected end with the previous three.</p></section>`;
  return `<div class="page-title"><div><div class="eyebrow">Ireland · Digital Power</div><h1>Installers</h1><p>Track activity, compare performance and inspect the accounts behind the change.</p></div><div class="panel-actions"><button class="primary" data-action="installer-open-import">Import installer data</button><button data-action="installer-analytics-export">Export KPI table</button><button data-action="installer-export">Export monthly totals</button></div></div>
${X.installerTabNav('overview')}${A.installerDashboard(state,ui,report,{rankingSlot:ranking})}

${A.installerHeatmap(shown,f,report)}<details class="installer-account-management panel editing" id="installer-account-management"><summary><strong>Account management</strong><span>Review identity matches, confirm unions and undo previous unions</span></summary><div class="installer-management-body"><div class="installer-management-actions"><div><h3>Unify verified accounts</h3><p class="table-note">Select two or more accounts in the ranking before reviewing a union. Existing monthly values are summed only after confirmation.</p></div><button data-action="installer-merge" ${selected.size<2?'disabled':''}>Review union (${selected.size})</button></div><section class="panel installer-account-subpanel"><div class="panel-head"><h2>Suggested matches</h2></div><p class="table-note">Spelling suggestions only. Confirm which names belong to the same installer. All confirmed matches are summed.</p>${suggestions.map(s=>`<div class="installer-suggestion"><div><strong>${s.names.map(e).join(' + ')}</strong><p class="table-note">${e(s.reason)}</p></div><button data-installer-suggest="${e(s.ids.join(','))}">Review union</button></div>`).join('')||'<p>No similar names awaiting review.</p>'}${suggestions.length===20?'<p class="table-note">Showing the first 20 suggestions. More may appear after these are resolved.</p>':''}</section>
<section class="panel installer-account-subpanel"><div class="panel-head"><h2>Account union history</h2></div>${historyList(d.merges,'account unions',unionHistoryLine)}</section></div></details>`;
}

// The same importer and preview formerly shown in Installers are now owned by Data.
// No import calculation or validation is duplicated.
export function installerImportView(state,ui){
  const d=state.installers,pending=ui.installerPending;
  return `<div class="page-title"><div><div class="eyebrow">Data workspace</div><h2>Installer activation imports</h2><p>Import, review and audit installer monthly snapshots. Analysis stays in the Installers workspace.</p></div><div class="panel-actions"><button data-nav="installers">Open Installer Analytics</button></div></div>
<section class="panel"><details open><summary>Import installer activations</summary><p class="table-note">One installer per row, monthly columns and an optional trailing Total column (ignored). Blank monthly cells = zero. Repeated names are summed. Summary rows such as === 总计 === are ignored. Reimporting replaces source/month snapshots. Full reporting scope requires explicit confirmation; partial imports never infer zero from absent companies.</p><label class="field">Excel or CSV file<input id="installer-file" type="file" accept=".xlsx,.csv" ${ui.demo||ui.installerLoading?'disabled':''}></label>${ui.installerLoading?'<p role="status">Reading worksheet…</p>':''}${ui.installerError?`<p class="notice error" role="alert">${e(ui.installerError)}</p>`:''}${pending?installerPreview(state,pending):''}</details></section>
<section class="panel"><div class="panel-head"><h2>Installer import history</h2></div>${historyList(d.imports,'installer imports',importHistoryLine)||'<p class="table-note">No installer imports yet.</p>'}</section>`;
}

export function installerPreview(state,p){
  const v=p.validation,preview=D.installerImportPreview(state,v),changes=preview.filter(r=>r.action!=='Unchanged');
  return `<div class="form-row"><label class="field">Worksheet<select id="installer-sheet">${p.workbook.names.map(name=>`<option ${name===p.sheet?'selected':''}>${e(name)}</option>`).join('')}</select></label><label class="field">Header row<input id="installer-header" type="number" min="1" max="${p.rows.length}" value="${p.headerRow+1}"></label><label class="field">Installer-name column<select id="installer-name-column">${(p.rows[p.headerRow]??[]).map((c,i)=>`<option value="${i}" ${i===p.nameColumn?'selected':''}>${D.columnName(i)}: ${e(D.cellValue(c)??'')}</option>`).join('')}</select></label></div><p>${v.sources.length} source names · ${v.months.length} months · ${v.duplicates} repeated rows summed · ${v.blankZeros} blanks converted to zero · ${changes.length} changed values</p><p>${v.ignoredTotal?'Trailing Total column ignored.':''}</p>${v.errors.length?`<div class="notice error"><ul>${v.errors.slice(0,20).map(x=>`<li>${e(x)}</li>`).join('')}</ul><p>${v.errors.length} errors; nothing has been saved.</p></div>`:''}${v.warnings.map(w=>`<p class="table-note">${e(w)}</p>`).join('')}<details><summary>Review monthly changes (${changes.length})</summary><div class="table-wrap"><table><thead><tr><th>Source → Account</th><th>Month</th><th>Previous</th><th>Incoming</th><th>Action</th></tr></thead><tbody>${changes.slice(0,200).map(r=>`<tr><td>${e(r.label)} → ${e(r.account)}</td><td>${e(r.month)}</td><td>${n(r.previous)}</td><td>${n(r.quantity)}</td><td>${e(r.action)}</td></tr>`).join('')}</tbody></table></div>${changes.length>200?'<p>First 200 changes shown. Download the full preview to review every value.</p>':''}</details><button data-action="installer-preview-export">Download full preview CSV</button><form data-form="installer-import"><label class="field">Reporting coverage<select name="scope" required><option value="partial">Partial update / coverage not confirmed (default)</option><option value="full">Full installer population for all imported months</option></select></label><p class="table-note">Only select Full when every installer in the reporting population is represented, and absent installers genuinely have zero activations for each imported month. Full scope can make previously missing aliases interpretable; this affects growth and retention.</p><label><input type="checkbox" name="fullScopeConfirmed"> If selecting Full, I confirm the file covers the full installer population and absent companies had zero activations in those months.</label><label><input type="checkbox" name="approved" required> I reviewed the import. Blank monthly cells replace previous values with zero; repeated names are summed.</label><div class="dialog-actions"><button type="button" data-action="installer-cancel">Cancel</button><button type="submit" class="primary" ${v.errors.length?'disabled':''}>Confirm installer import</button></div></form>`;
}
export function installerMergePreview(state,ids){
  const accounts=ids.map(id=>state.installers.accounts[id]).filter(Boolean),months=[...new Set(accounts.flatMap(a=>Object.keys(D.installerMonthly(state,a.id))))].sort();
  return `<form data-form="installer-merge"><label class="field">Consolidated installer name<input name="name" required maxlength="200" value="${e(accounts[0]?.name??'')}"></label><p>Monthly values will be summed. Original source records remain available, and future imports replace their corresponding source/month snapshots.</p><div class="table-wrap"><table><thead><tr><th>Month</th>${accounts.map(a=>`<th>${e(a.name)}</th>`).join('')}<th>Consolidated</th></tr></thead><tbody>${months.map(month=>{const values=accounts.map(a=>D.installerMonthly(state,a.id)[month]);return `<tr><td>${e(month)}</td>${values.map(v=>`<td>${n(v)}</td>`).join('')}<td><strong>${n(values.reduce((sum,v)=>sum+(v??0),0))}</strong></td></tr>`;}).join('')}</tbody></table></div><p class="table-note">— means that source has no record for that month. Consolidation sums available values and preserves that distinction in source evidence.</p><div class="dialog-actions"><button type="button" data-close="modal">Cancel</button><button type="submit" class="primary">Unify and sum activations</button></div></form>`;
}
export function installerDetail(state,id){
  const sources=Object.values(state.installers.sources).filter(s=>s.accountId===id),monthly=D.installerMonthly(state,id);
  return `<p>All available months. Original source quantities are preserved.</p><div class="table-wrap"><table><thead><tr><th>Month</th>${sources.map(s=>`<th>${e(s.label)}</th>`).join('')}<th>Consolidated</th></tr></thead><tbody>${Object.keys(monthly).sort().map(month=>`<tr><td>${e(month)}</td>${sources.map(s=>{const r=s.months[month],active=D.installerEffectiveRecord(state,s,month),superseded=!!r&&!active;return `<td>${n(active?.quantity??(state.installers.coverage?.[month]?.mode==='full'?0:null))}${r?`<details><summary>${superseded?'Historical — superseded':'Source'}</summary>${e(r.source.filename)} · ${e(r.source.sheet)}<br>${r.source.cells.map(c=>`${e(c.cell)}: ${n(c.quantity)}${c.blank?' (blank → zero)':''}`).join('<br>')}</details>`:''}</td>`;}).join('')}<td>${n(monthly[month])}</td></tr>`).join('')}</tbody></table></div>`;
}
